import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { formatMoney, formatToken, formatTokenAmount, EducationalTooltip, ETH_ICON, USDC_ICON } from './Shared';

interface LimitPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const LimitPanel: React.FC<LimitPanelProps> = ({ amount, onAmountChange, balance }) => {
  const [limitPrice, setLimitPrice] = useState('3208.93');
  const [expiry, setExpiry] = useState('24h');
  const [postOnly, setPostOnly] = useState(false);

  const ETH_PRICE = 3208.93;
  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;

  const simulation = useMemo(() => {
    const pay = numericPay;
    const limitP = parseFloat(limitPrice) || ETH_PRICE;
    const limitValue = pay * limitP;

    const distanceToMarket = ((limitP - ETH_PRICE) / ETH_PRICE) * 100;
    const isBelowMarketSell = distanceToMarket < 0;
    const postOnlyWarning = postOnly && isBelowMarketSell;

    // Fees
    const platformFee = limitValue * 0.0005;
    const networkFee = 9.75;
    const netLimitReceive = Math.max(0, limitValue - platformFee - networkFee);
    const effectivePrice = pay > 0 ? netLimitReceive / pay : 0;

    // Probability & Intelligence
    let expiryHours = 24;
    if(expiry === '10m') expiryHours = 0.16;
    else if(expiry === '3d') expiryHours = 72;
    else if(expiry === '7d') expiryHours = 168;
    else if(expiry === 'GTC') expiryHours = 720;

    const HOURLY_VOLATILITY = 0.035 / Math.sqrt(24);
    const stdDevsNeeded = (Math.abs(distanceToMarket)/100) / (HOURLY_VOLATILITY * Math.sqrt(expiryHours));
    let rawProb = 100 * Math.exp(-0.5 * Math.pow(stdDevsNeeded, 2));
    if (isBelowMarketSell) rawProb = 100;
    const execProbability = Math.round(Math.min(99, Math.max(1, rawProb)));

    let timeHorizon = 'Instant';
    let timeRange = 'Now';
    if (!isBelowMarketSell) {
        const expectedHours = (Math.abs(distanceToMarket)) * 12; // simplified velocity
        if(expectedHours < 1) { timeHorizon = '< 1 Hour'; timeRange = '10m - 90m'; }
        else if(expectedHours < 24) { timeHorizon = `~${Math.ceil(expectedHours)} Hours`; timeRange = '1d'; }
        else { timeHorizon = `~${Math.ceil(expectedHours/24)} Days`; timeRange = 'Multi-day'; }
    }

    const dailyYieldLoss = limitValue * 0.042 * (expiryHours/8760);

    return {
        limitValue,
        netLimitReceive,
        effectivePrice,
        distanceToMarket,
        isBelowMarketSell,
        postOnlyWarning,
        platformFee,
        networkFee,
        execProbability,
        probColor: execProbability > 65 ? 'text-emerald-500' : 'text-amber-500',
        timeHorizon,
        timeRange,
        dailyYieldLoss,
        structureLabel: limitP < 3180 ? 'BELOW SUPPORT' : limitP > 3280 ? 'BREAKOUT' : 'IN RANGE',
        structureColor: limitP > 3280 ? 'text-emerald-400' : 'text-zinc-400',
        tooltips: {
            prob: isBelowMarketSell ? "Executes immediately as Taker." : `Statistical probability of reaching target in ${expiry}.`,
            cost: `Forgone yield (4.2% APY) by locking funds.`
        }
    };
