interface SwapPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const SwapPanel: React.FC<SwapPanelProps> = ({ amount, onAmountChange, balance }) => {
  // --- STATE PERSISTENCE & DATA ---
  const [recipientMode, setRecipientMode] = useState(false);
  const [recipientAddress, setRecipientAddress] = useState(''); // Persist even if toggled off
  const [gasSpeed, setGasSpeed] = useState<'slow' | 'normal' | 'fast'>('normal');
  const [isGasSelectorOpen, setIsGasSelectorOpen] = useState(false);

  // Token State
  const [payToken, setPayToken] = useState({ sym: 'ETH', name: 'Ethereum' });
  const [receiveToken, setReceiveToken] = useState({ sym: 'USDC', name: 'USD Coin' });
  const [selectingSide, setSelectingSide] = useState<'pay' | 'receive' | null>(null);

  // Settings State (Intelligence Panel)
  const [slippage, setSlippage] = useState(0.5);
  const [useMEVShield, setUseMEVShield] = useState(true);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false); // Controls the Intelligence details view
  const [isDetailsOpen, setIsDetailsOpen] = useState(false); // Progressive disclosure for Score details

  // UX State
  const [isReviewing, setIsReviewing] = useState(false);
  const [reviewTimer, setReviewTimer] = useState(15);
  const [isSimulating, setIsSimulating] = useState(false);

  const ETH_PRICE = 3208.93;
  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;
  const hasAmount = numericPay > 0;

  // --- EFFECT: Simulate Route Calculation when Amount Changes ---
  useEffect(() => {
      if (hasAmount) {
          setIsSimulating(true);
          // Auto-close details when recalculating to reduce noise
          setIsDetailsOpen(false); 
          const timer = setTimeout(() => setIsSimulating(false), 800); // Fake latency
          return () => clearTimeout(timer);
      }
  }, [amount, payToken, receiveToken]);

  // --- REVIEW TIMER ---
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isReviewing) {
        setReviewTimer(15);
        interval = setInterval(() => {
            setReviewTimer(prev => {
                if (prev <= 1) {
                    setIsReviewing(false); 
                    return 15;
