// --- TYPES ---
interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
}

// --- SYNTHETIC CHART GENERATOR (BTC Logic) ---
const generateSyntheticCandles = (count: number, startPrice: number): Candle[] => {
  const candles: Candle[] = [];
  let currentPrice = startPrice;
  const now = Date.now();
  const timeStep = 15 * 60 * 1000; // 15 min

  for (let i = count; i > 0; i--) {
    const volatility = currentPrice * 0.002; // 0.2% volatility per candle
    const trend = (Math.random() - 0.5) * volatility * 0.5; // Slight drift

    const open = currentPrice;
    const close = open + ((Math.random() - 0.5) * volatility) + trend;

    // Wicks
    const high = Math.max(open, close) + (Math.random() * volatility * 0.8);
    const low = Math.min(open, close) - (Math.random() * volatility * 0.8);

    candles.push({
      time: now - (i * timeStep),
      open,
      high,
      low,
      close
    });

    currentPrice = close;
  }
  return candles;
};

// --- SANITY CHECK MODAL ---
interface SanityCheckProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  leverage: number;
  side: 'long' | 'short';
  liqPrice: number;
  distance: string;
}

const SanityCheckModal: React.FC<SanityCheckProps> = ({ isOpen, onClose, onConfirm, leverage, side, liqPrice, distance }) => {
  const [timer, setTimer] = useState(3);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isOpen) {
      setTimer(3);
      interval = setInterval(() => {
        setTimer((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-[#09090b] border border-rose-500/30 rounded-3xl w-full max-w-sm shadow-[0_0_50px_-10px_rgba(244,63,94,0.3)] overflow-hidden transform animate-in zoom-in-95 duration-200">
        <div className="bg-rose-500/10 p-5 border-b border-rose-500/20 flex items-center gap-4">
           <div className="p-2.5 bg-rose-500/20 rounded-full text-rose-500 animate-pulse">
              <Skull size={20} />
           </div>
           <div>
              <h2 className="text-base font-black text-white uppercase tracking-wide">High Leverage Alert</h2>
              <p className="text-rose-400 text-[10px] font-bold uppercase tracking-widest">{leverage}x Leverage</p>
           </div>
        </div>
        <div className="p-6 space-y-5">
           <p className="text-xs text-zinc-300 font-medium leading-relaxed">
             You are opening a <span className={side === 'long' ? 'text-emerald-500 font-bold' : 'text-rose-500 font-bold'}>{side.toUpperCase()}</span> position. 
             Price movement of <span className="text-white font-bold bg-rose-500/20 px-1 rounded">{distance}%</span> against you triggers immediate liquidation.
           </p>
           <div className="bg-black/40 border border-white/5 rounded-xl p-3 flex justify-between items-center">
