              <span className="text-sm font-mono font-bold text-rose-500">${liqPrice.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span>
           </div>
           <div className="flex gap-3 pt-2">
              <button onClick={onClose} className="flex-1 py-3 rounded-xl font-bold text-[10px] uppercase tracking-widest bg-zinc-800 hover:bg-zinc-700 text-zinc-400 hover:text-white transition-colors">Cancel</button>
              <button onClick={onConfirm} disabled={timer > 0} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${timer > 0 ? 'bg-zinc-900 border border-zinc-800 text-zinc-600 cursor-not-allowed' : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/50'}`}>
